'use client'
import { Check, Copy } from 'lucide-react'
import { useCopy } from '@/hooks/useCopy'
import { cn } from '@/lib/cn'

// An identifier or an endpoint as typed, with a button that copies it (CopyText.vue): the value in 12px Geist Mono,
// cut with an ellipsis when it runs out of room (the whole value in its title), and a 20px quiet button whose glyph turns
// to a check for 1.5s. The button is round, as the console draws it, and grows a 44px place to land on phones. One value
// per copy text; never a secret after it was first shown.
export interface CopyTextProps {
  value: string
  label: string
  className?: string
}

export function CopyText({ value, label, className }: CopyTextProps) {
  const { copied, copy } = useCopy()
  return (
    <span data-ds="copy-text" className={cn('inline-flex max-w-full min-w-0 items-center gap-1', className)}>
      <code className="truncate font-code text-meta leading-5" title={value}>{value}</code>
      <button
        type="button"
        className="relative inline-flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-full text-fg-muted transition-colors duration-150 hover:bg-surface-sunken hover:text-fg pointer-coarse:after:absolute pointer-coarse:after:-inset-3 pointer-coarse:after:content-[''] max-md:after:absolute max-md:after:-inset-3 max-md:after:content-['']"
        aria-label={copied ? `${label} copied` : `copy ${label}`}
        onClick={(e) => { e.stopPropagation(); void copy(value) }}
      >
        {copied ? <Check size={12} strokeWidth={1.5} aria-hidden="true" /> : <Copy size={12} strokeWidth={1.5} aria-hidden="true" />}
      </button>
    </span>
  )
}

export default CopyText

'use client'
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * A copy button's state: copy(text) writes the clipboard, and copied is true for 1.5s after. Where the Clipboard API is
 * refused (a browser or a frame that denies it), the older copy command still works inside the click. Only if both are
 * refused does it answer false, and the text stays selectable.
 */
export function useCopy(ms = 1500) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  const copy = useCallback(async (text: string): Promise<boolean> => {
    try {
      await navigator.clipboard.writeText(text)
    }
    catch {
      if (!copyByCommand(text)) return false
    }
    setCopied(true)
    clearTimeout(timer.current)
    // ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
    timer.current = setTimeout(() => setCopied(false), ms)
    return true
  }, [ms])
  return { copied, copy }
}

// The older way: select the text in an unseen field, run the copy command, hand focus back.
function copyByCommand(text: string) {
  const back = document.activeElement as HTMLElement | null
  const field = document.createElement('textarea')
  field.value = text
  field.setAttribute('readonly', '')
  field.style.position = 'fixed'
  field.style.opacity = '0'
  document.body.appendChild(field)
  field.select()
  let ok = false
  try { ok = document.execCommand('copy') }
  catch { ok = false }
  field.remove()
  back?.focus()
  return ok
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
